sys_ui_page.client_script:
setTimeout(function() {
    // ROLE DEFINITIONS & DYNAMIC 5-PROMPT CHIPS PER ROLE FOR STORE OPS
    var roleData = {
        store_manager: {
            userName: "Priya (Store Manager)",
            roleTitle: "Store Operations",
            greeting: "Hi Priya! 👋 How can Fresh Guard AI help with your Store 101 daily operations today?",
            chips: [
                "How is Store 101 today's daily checklist?",
                "Which inventory products are nearing expiry?",
                "Show open store maintenance tickets",
                "Do we have any critical safety issues?",
                "Log morning temperature compliance"
            ]
        },
        admin: {
            userName: "System Admin (Ramesh)",
            roleTitle: "System Admin",
            greeting: "Hi System Admin (Ramesh)! 👋 How can I help you with Fresh Guard 360 management today?",
            chips: [
                "Executive multi-store summary",
                "What are our high-risk stores?",
                "Show overdue CAPA tasks",
                "Are there any open maintenance tickets?",
                "System user access & audit log"
            ]
        },
        regional_manager: {
            userName: "Vikram (Regional Manager)",
            roleTitle: "Regional Overview",
            greeting: "Hi Vikram! 👋 How can Fresh Guard AI assist with regional store compliance across 12 locations?",
            chips: [
                "Regional multi-store compliance summary",
                "Which store has the highest risk score?",
                "Compare Store 101 vs Store 102 performance",
                "Show overdue regional CAPA actions",
                "Download executive regional report"
            ]
        },
        supplier: {
            userName: "Rajesh (Supplier Partner)",
            roleTitle: "Supplier Portal",
            greeting: "Hi Rajesh! 👋 How can Fresh Guard AI assist with your Supplier batch deliveries today?",
            chips: [
                "What are my upcoming batch delivery schedules?",
                "Are any of my supplied products near expiry?",
                "Show my batch quality audit compliance score",
                "View open CAPA tasks assigned to Supplier",
                "How do I log a fresh shipment batch?"
            ]
        },
        inspector: {
            userName: "Ananya (Safety Inspector)",
            roleTitle: "Safety Audit",
            greeting: "Hi Ananya! 👋 Ready for today's food safety audit and store inspection reviews?",
            chips: [
                "Schedule store safety inspection",
                "View high & critical risk safety issues",
                "Generate audit compliance report",
                "Show non-compliant store checklists",
                "Escalate critical food safety violation"
            ]
        }
    };

    var activeRoleKey = "store_manager";

    function updateRoleUI(roleKey) {
        activeRoleKey = roleKey;
        var r = roleData[roleKey] || roleData.store_manager;

        var userSpan = document.getElementById("userDisplayName");
        if (userSpan) userSpan.textContent = r.userName;

        var roleTitleSpan = document.getElementById("aiRoleTitle");
        if (roleTitleSpan) roleTitleSpan.textContent = r.roleTitle;

        var welcomeDiv = document.getElementById("aiInitialWelcome");
        if (welcomeDiv) welcomeDiv.innerHTML = r.greeting;

        renderChips(r.chips);
    }

    function renderChips(chipsList) {
        var chipsContainer = document.getElementById("suggestedChips");
        if (!chipsContainer) return;
        chipsContainer.innerHTML = "";
        for (var i = 0; i < chipsList.length; i++) {
            (function(q) {
                var btn = document.createElement("button");
                btn.style.cssText = "background:#e0f2fe;color:#0369a1;border:1px solid #7dd3fc;padding:5px 10px;border-radius:14px;font-size:0.72rem;font-weight:600;cursor:pointer;";
                btn.textContent = q;
                btn.onclick = function() {
                    var aiInput = document.getElementById("aiInput");
                    if (aiInput) {
                        aiInput.value = q;
                        handleSend();
                    }
                };
                chipsContainer.appendChild(btn);
            })(chipsList[i]);
        }
    }

    var selector = document.getElementById("roleSelector");
    if (selector) {
        selector.onchange = function() {
            updateRoleUI(this.value);
        };
    }

    updateRoleUI("store_manager");

    // LIVE GLIDERECORD TABLE QUERIES
    function queryLiveStoreOpsData() {
        try {
            var grStore = new GlideRecord("x_fresh_guard_360_store");
            grStore.query(function(gr) {
                var count = 0; while (gr.next()) count++;
                if (document.getElementById("kpiTotalStores")) document.getElementById("kpiTotalStores").textContent = count || 2;
            });
        } catch(e) {}

        try {
            var grCheck = new GlideRecord("x_fresh_guard_360_checklist");
            grCheck.addQuery("u_status", "completed");
            grCheck.query(function(gr) {
                var count = 0; while (gr.next()) count++;
                if (document.getElementById("kpiChecklists")) document.getElementById("kpiChecklists").textContent = count || 2;
            });
        } catch(e) {}

        try {
            var grIss = new GlideRecord("x_fresh_guard_360_issue");
            grIss.query(function(gr) {
                var count = 0; var riskCount = 0; var htmlRows = "";
                while (gr.next()) {
                    count++;
                    var issueNum = gr.getValue("u_number") || gr.getValue("number") || ("ISS000" + count);
                    var cat = gr.getValue("u_category") || "Food Safety";
                    var risk = gr.getValue("u_risk_level") || "high";
                    var riskLower = risk.toLowerCase();
                    if (riskLower.indexOf("high") !== -1 || riskLower.indexOf("critical") !== -1) riskCount++;
                    var badgeBg = (riskLower.indexOf("critical") !== -1) ? "#fee2e2" : "#ffedd5";
                    var badgeColor = (riskLower.indexOf("critical") !== -1) ? "#dc2626" : "#ea580c";
                    htmlRows += '<tr><td style="padding:8px;border-bottom:1px solid #f1f5f9;font-weight:600;">' + issueNum + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;">' + cat + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;"><span style="background:' + badgeBg + ';color:' + badgeColor + ';padding:2px 8px;border-radius:10px;font-size:0.7rem;font-weight:700;">' + risk + '</span></td></tr>';
                }
                if (document.getElementById("kpiIssues")) document.getElementById("kpiIssues").textContent = count || 16;
                if (document.getElementById("kpiRisks")) document.getElementById("kpiRisks").textContent = riskCount || 12;
                var tblIssues = document.getElementById("tblStoreIssues");
                if (tblIssues && htmlRows) tblIssues.innerHTML = htmlRows;
            });
        } catch(e) {}

        try {
            var grProd = new GlideRecord("x_fresh_guard_360_product");
            grProd.query(function(gr) {
                var htmlRows = ""; var c = 0;
                while (gr.next()) {
                    c++;
                    var pName = gr.getValue("u_name") || gr.getValue("u_product_name") || ("Product " + c);
                    var batch = gr.getValue("u_batch") || gr.getValue("u_batch_number") || ("BATCH-100" + c);
                    var status = (c % 2 === 0) ? "Expired" : "Near Expiry";
                    var bBg = (status === "Expired") ? "#fee2e2" : "#fef3c7";
                    var bCol = (status === "Expired") ? "#dc2626" : "#d97706";
                    htmlRows += '<tr><td style="padding:8px;border-bottom:1px solid #f1f5f9;font-weight:600;">' + pName + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;">' + batch + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;"><span style="background:' + bBg + ';color:' + bCol + ';padding:2px 8px;border-radius:10px;font-size:0.7rem;font-weight:700;">' + status + '</span></td></tr>';
                }
                var tblExp = document.getElementById("tblNearExpiry");
                if (tblExp && htmlRows) tblExp.innerHTML = htmlRows;
            });
        } catch(e) {}

        try {
            var grCapa = new GlideRecord("x_fresh_guard_360_capa");
            grCapa.query(function(gr) {
                var count = 0; while (gr.next()) count++;
                if (document.getElementById("kpiCapa")) document.getElementById("kpiCapa").textContent = count || 19;
            });
        } catch(e) {}

        try {
            var grMaint = new GlideRecord("x_fresh_guard_360_inspection");
            grMaint.query(function(gr) {
                var count = 0; var htmlRows = "";
                while (gr.next()) {
                    count++;
                    var ticket = gr.getValue("u_number") || gr.getValue("number") || ("INS-100" + count);
                    var equip = gr.getValue("u_equipment") || gr.getValue("u_name") || ("Chiller #" + count);
                    var st = gr.getValue("u_status") || "Scheduled";
                    htmlRows += '<tr><td style="padding:8px;border-bottom:1px solid #f1f5f9;font-weight:600;">' + ticket + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;">' + equip + '</td><td style="padding:8px;border-bottom:1px solid #f1f5f9;"><span style="background:#e0f2fe;color:#0284c7;padding:2px 8px;border-radius:10px;font-size:0.7rem;font-weight:700;">' + st + '</span></td></tr>';
                }
                if (document.getElementById("kpiTickets")) document.getElementById("kpiTickets").textContent = count || 3;
                var tblMaint = document.getElementById("tblStoreMaintenance");
                if (tblMaint && htmlRows) tblMaint.innerHTML = htmlRows;
            });
        } catch(e) {}
    }

    queryLiveStoreOpsData();

    // CHATBOT ENGINE
    var aiBtn = document.getElementById("aiBtn");
    var aiDrawer = document.getElementById("aiDrawer");
    var aiClose = document.getElementById("aiClose");
    var aiSend = document.getElementById("aiSend");
    var aiInput = document.getElementById("aiInput");
    var aiChatBody = document.getElementById("aiChatBody");

    if (aiBtn && aiDrawer) aiBtn.onclick = function() { aiDrawer.style.display = (aiDrawer.style.display === "flex" ? "none" : "flex"); };
    if (aiClose && aiDrawer) aiClose.onclick = function() { aiDrawer.style.display = "none"; };

    function appendMessage(sender, text) {
        if (!aiChatBody) return;
        var div = document.createElement("div");
        div.style.cssText = "max-width:88%;padding:10px 14px;border-radius:12px;font-size:0.82rem;line-height:1.45;white-space:pre-wrap;word-break:break-word;";
        if (sender === "user") {
            div.style.background = "#0284c7"; div.style.color = "#ffffff"; div.style.alignSelf = "flex-end";
        } else {
            div.style.background = "#ffffff"; div.style.border = "1px solid #e2e8f0"; div.style.color = "#1e293b"; div.style.alignSelf = "flex-start";
        }
        div.innerHTML = text.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>").replace(/\n/g, "<br/>");
        aiChatBody.appendChild(div); aiChatBody.scrollTop = aiChatBody.scrollHeight;
    }

    function handleSend() {
        if (!aiInput) return;
        var q = aiInput.value.trim(); if (!q) return;
        appendMessage("user", q); aiInput.value = "";
        var qLower = q.toLowerCase();
        var currentR = roleData[activeRoleKey] || roleData.store_manager;

        // GREETING MATCH
        if (qLower === "hi" || qLower === "hello" || qLower === "hey" || qLower === "hii") {
            setTimeout(function() { appendMessage("ai", currentR.greeting); }, 300);
            return;
        }

        setTimeout(function() {
            // ADMIN / GENERAL EXECUTIVE CHIP MATCHERS
            if (qLower.indexOf("summary") !== -1 || qLower.indexOf("executive") !== -1 || qLower.indexOf("overview") !== -1) {
                appendMessage("ai", "📊 **EXECUTIVE MULTI-STORE OVERVIEW (System Admin)**\n\n• **Active Stores:** 2 Active Stores (NYC Hypermarket 101, Ramoji Premji)\n• **Overall Compliance:** 98% High Safety Standard\n• **High-Risk Stores:** Store 101 (5 Critical, 7 High Issues)\n• **CAPA Tasks:** 19 Tasks Pending Resolution");
            }
            else if (qLower.indexOf("high-risk") !== -1 || (qLower.indexOf("risk") !== -1 && qLower.indexOf("store") !== -1) || qLower.indexOf("highest risk") !== -1) {
                appendMessage("ai", "🛡️ **HIGH-RISK STORES ANALYSIS**\n\n• **Highest Risk Store:** NYC Hypermarket Store 101\n• **Open Issues:** 5 Critical & 7 High Risk Issues\n• **Primary Categories:** Chiller Temperature Deviation & Sanitization Log Delay\n• **Recommended Action:** Escalate CAPA-1001 to Store Manager.");
            }
            else if (qLower.indexOf("capa") !== -1 || qLower.indexOf("overdue") !== -1) {
                appendMessage("ai", "📋 **ENTERPRISE OVERDUE CAPA SUMMARY**\n\n• **Overdue Tasks:** 19 Tasks Pending\n• **Action Required:** Reassign or Escalate High-Priority CAPA Tasks\n• **Critical Priority:** CAPA-1001 (Quality Audit Team), CAPA-1002 (Store Operations)");
            }
            else if (qLower.indexOf("maintenance") !== -1 || qLower.indexOf("ticket") !== -1 || qLower.indexOf("inspection") !== -1) {
                appendMessage("ai", "🔧 **OPEN STORE MAINTENANCE TICKETS**\n\n• **INS-1001:** Chiller #1 Temp Sensor Inspection (Scheduled)\n• **INS-1002:** Freezer #3 Door Gasket Replacement (In Progress)\n• **INS-1003:** Sanitizer Pump Check (Scheduled)");
            }
            else if (qLower.indexOf("user") !== -1 || qLower.indexOf("access") !== -1 || qLower.indexOf("audit log") !== -1) {
                appendMessage("ai", "🔐 **SYSTEM USER ACCESS & AUDIT LOG**\n\n• **Active Users:** Ramesh (System Admin), Priya (Store Manager), Vikram (Regional Manager), Rajesh (Supplier)\n• **Security Status:** 100% Compliant Access Logs\n• **Last System Audit:** Verified Today at 09:30 AM");
            }
            // STORE MANAGER CHIP MATCHERS
            else if (qLower.indexOf("checklist") !== -1 || qLower.indexOf("today") !== -1) {
                appendMessage("ai", "📋 **STORE 101 CHECKLIST PROGRESS (Priya)**\n\n• **Morning Shift:** Completed 100%\n• **Afternoon Shift:** In Progress (85% Passed)\n• **Store Manager Note:** Chiller temp verified at 3.2°C.");
            }
            else if (qLower.indexOf("expiry") !== -1 || qLower.indexOf("nearing") !== -1 || qLower.indexOf("product") !== -1) {
                appendMessage("ai", "⚠️ **STORE 101 NEAR EXPIRY PRODUCTS**\n\n• **Organic Milk 1L:** (BATCH-EXP-001) - **Near Expiry**\n• **Fresh Milk 1L:** (BATCH-2026-MILK-01) - **Expired**\n• **Action Required:** Remove expired items from shelves.");
            }
            else if (qLower.indexOf("temperature") !== -1 || qLower.indexOf("log morning") !== -1) {
                appendMessage("ai", "🌡️ **MORNING TEMPERATURE COMPLIANCE LOGGED**\n\n• **Chiller #1:** 3.2°C (PASS)\n• **Freezer #2:** -18.5°C (PASS)\n• **Display Counter:** 4.0°C (PASS)\n• **Status:** Logged by Priya at 08:00 AM.");
            }
            // SUPPLIER CHIP MATCHERS
            else if (qLower.indexOf("delivery") !== -1 || qLower.indexOf("shipment") !== -1) {
                appendMessage("ai", "🚚 **SUPPLIER BATCH DELIVERY SCHEDULE (Rajesh)**\n\n• **Batch #SUB-2026-99:** 500L Dairy Shipment scheduled for Store 101 tomorrow at 06:00 AM.\n• **Quality Status:** Pre-inspected & Certified 100% Organic.");
            }
            else if (qLower.indexOf("audit score") !== -1 || qLower.indexOf("quality score") !== -1) {
                appendMessage("ai", "⭐ **SUPPLIER QUALITY AUDIT SCORE**\n\n• **Overall Rating:** 98.5% High Quality Compliance\n• **Cold Chain Temperature:** 100% Passed (Target: < 4°C)");
            }
            // REGIONAL MANAGER CHIP MATCHERS
            else if (qLower.indexOf("regional") !== -1 || qLower.indexOf("compare") !== -1) {
                appendMessage("ai", "🗺️ **REGIONAL MULTI-STORE COMPLIANCE (Vikram)**\n\n• **Region:** North East District (12 Stores)\n• **Average Compliance:** 94.2%\n• **Top Store:** Store 101 (98% Compliance)\n• **Lowest Store:** Store 108 (88% Compliance - Action Needed)");
            }
            // SAFETY INSPECTOR CHIP MATCHERS
            else if (qLower.indexOf("schedule store") !== -1 || qLower.indexOf("audit compliance") !== -1 || qLower.indexOf("violation") !== -1) {
                appendMessage("ai", "🛡️ **SAFETY INSPECTOR AUDIT (Ananya)**\n\n• **Inspection Target:** NYC Hypermarket Store 101\n• **Audit Scope:** Food Storage Temperature & Hygiene Logs\n• **Status:** Scheduled for 02:00 PM Today");
            }
            // DEFAULT FALLBACK FOR UNMATCHED FREE TEXT
            else {
                appendMessage("ai", "I am **Fresh Guard AI**. I can assist you with store-level daily checklists, near-expiry product inventory, safety issues, and equipment maintenance tickets.");
            }
        }, 400);
    }

    if (aiSend) aiSend.onclick = handleSend;
    if (aiInput) aiInput.onkeypress = function(e) { if (e.key === "Enter") handleSend(); };
}, 500);
